PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (SUM(xsd:decimal(?amount)) AS ?totalAmount)
WHERE {
  ?cashFlow ex:amount ?amount;
           ex:date ?date.
  FILTER(CONTAINS(LCASE(STR(?date)), "last 12 months"))
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?rebalance) AS ?totalRebalances)
WHERE {
  ?rebalance a ex:RebalancingAction;
             schema1:value "Overweight".
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(xsd:decimal(?newAllocation)) AS ?averageNewAllocation) (SUM(xsd:decimal(?change)) AS ?totalChange) (COUNT(DISTINCT ?scenario) AS ?countScenario) (IF(xsd:decimal(?totalChange) > 0, "increased", "decreased") AS ?allocationChangeType)
WHERE {
    ?scenario a ex:ScenarioRebalancing_AllocationChange;
              ex:hasNewAllocationPct ?newAllocation;
              ex:hasAllocationChange ?change.
}
GROUP BY IF(xsd:decimal(?totalChange) > 0, "increased", "decreased")

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?scenarioRebalanceId (SUM(xsd:decimal(?currentAllocationPct)) AS ?totalCurrentAllocation) WHERE {
  ?rebalancing ex:scenarioRebalanceId ?scenarioRebalanceId;
               ex:currentAllocationPct ?currentAllocationPct.
  FILTER CONTAINS(LCASE(STR(?scenario)), "market")
} GROUP BY ?scenarioRebalanceId

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sectorName (COUNT(?investor) AS ?count) WHERE {
  ?allocation ex:hasSector ?sector .
  ?allocation ex:sectorName ?sectorName ;
             ex:hasInvestor ?investor .
} GROUP BY ?sectorName ORDER BY DESC(?count) LIMIT 1

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?rebalance) AS ?countOfUnderweightActions)
WHERE {
  ?rebalance a ex:RebalancingAction;
             schema1:action ?action.
  FILTER(LCASE(STR(?action)) = "underweight")
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(xsd:decimal(?newAllocation)) AS ?averageNewAllocation) (SUM(xsd:decimal(?change)) AS ?totalChange) (COUNT(DISTINCT ?scenario) AS ?countScenario) (IF(xsd:decimal(?totalChange) > 0, "increased", "decreased") AS ?allocationChangeType)
WHERE {
    ?scenario a ex:ScenarioRebalancing_AllocationChange;
              ex:hasNewAllocationPct ?newAllocation;
              ex:hasAllocationChange ?change.
}
GROUP BY IF(xsd:decimal(?totalChange) > 0, "increased", "decreased")

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(DISTINCT ?investor) AS ?totalInvestors)
WHERE {
  ?scenario a ex:ScenarioRebalancing;
            schema1:rationale "Interest Rate Hike";
            ex:hasInvestor ?investor.
  ?portfolio a ex:PortfolioHealth;
             ex:hasInvestor ?investor;
             schema1:riskScore "At Risk".
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName WHERE {
  ?investor schema1:hasHolding ?holding .
  FILTER NOT EXISTS {
    ?holding rdf:type ex:PortfolioHolding ;
             ex:purchaseDate ?lastYear .
    BIND(xsd:dateTime("now") AS ?currentDate)
    BIND(xsd:dateTime(CONCAT(YEAR(?currentDate), "-", MONTH(?currentDate), "-01")) AS ?yearStart)
    FILTER (?lastYear >= ?yearStart - 12MONTHS && ?lastYear <= ?yearStart)
  }
  ?investor schema1:investorName ?investorName .
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investmentName (AVG(xsd:decimal(?taxesPaid)) AS ?averageTaxes) WHERE {
  ?holding ex:hasInvestor ?investor .
  ?holding ex:taxesPaid ?taxesPaid ;
          ex:investmentName ?investmentName .
} GROUP BY ?investmentName ORDER BY ASC(xsd:decimal(?averageTaxes)) LIMIT 1

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?investor) AS ?count)
WHERE {
  ?investor a ex:InvestorProfile;
            schema1:riskTolerance "Conservative"@en;
            ex:diversificationScore ?diversificationScore.
  FILTER(xsd:decimal(?diversificationScore) < 50)
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (SUM(xsd:decimal(?cost)) AS ?totalInvestmentCost)
WHERE {
  ?holding a schema1:PortfolioHolding;
           ex:Cost ?cost;
           ex:purchaseDate ?date.
  FILTER(YEAR(?date) = 2022)
}
